INSERT INTO public.daily_quotes (day_number, message, description) VALUES
(1, 'ההתחלה מהווה את חצי העבודה', 'להתחיל לעשות – הוא החלק הכי קשה ומהותי. עצם זה שהתחלתם כבר שם אותך בנקודת יתרון. הרבה אנשים נתקעים לפני הפעולה – תכנון יתר, פחד מכישלון או דחיינות. התחלה = חצי מהניצחון!'),
(2, 'אנחנו מה שאנחנו עושים שוב ושוב. מצוינות, אם כך, אינה פעולה – אלא הרגל.', 'השגרות הקטנות שאתם מקיימים יוצרות את מי שאתם. אם אתם מתרגלים בחירה נכונה שוב ושוב – אתם הופכים לאנשים שמתקדמים, בלי קשר לתוצאה רגעית.'),
(3, 'משמעת קטנה שחוזרת על עצמה בעקביות מדי יום – מובילה להישגים גדולים שנבנים לאט עם הזמן.', 'השינויים הכי עוצמתיים לא מגיעים ממהפכות – אלא מהרגלים פשוטים שחוזרים על עצמם. זה יכול להיות כוס מים, הליכה בערב או להגיד "לא עכשיו" לדחף רגעי.'),
(4, 'הצלחה היא סך של מאמצים קטנים – שחוזרים על עצמם יום אחר יום.', 'לא לזלזל באף פעולה שאת/ה עושה. גם לבחור נכון בארוחה אחת, או ללכת לישון בזמן, אלו מאמצים שמצטברים ויוצרים תוצאה.'),
(5, 'זה לא ההתקדמות היומית, אלא ההפחתה היומית. תחתוך את מה שלא הכרחי.', 'לפעמים תהליך אמיתי מתחיל במה שאתם בוחרים לוותר עליו. עודף מחשבות, עומס מיותר, דפוסים לא בריאים. פשטות היא כוח.'),
(6, 'תדאג לגוף שלך – זה המקום היחיד שבו אתה חייב לגור.', 'לא מדובר רק בלהיראות טוב, אלא להרגיש בבית בתוך הגוף שלך. כשאתה בוחר בהתנהגויות שמטיבות איתך – אתה משדר לעצמך ערך.'),
(7, 'הביצוע הוא הגשר שמחבר בין מטרות להישגים.', 'הרבה אנשים רוצים שינוי – אבל רק מי שמוכן לחצות את הגשר, צעד אחרי צעד, גם כשזה נראה מונוטוני – יגיע באמת לתוצאה.'),
(8, 'השינוי הטוב ביותר הוא כזה שלא מרגיש כמו שינוי. — ג''יימס קליר', 'כשההרגל נטמע, אין מאבק – יש שגרה.'),
(9, 'ירגיל עצמו שלא יאכל אלא בזמנים ידועים ביום. — הלכות דעות ד'', 'סדר בזמני ארוחות חשוב לבריאות – הגוף אוהב הרגלים, לא כאוס.'),
(10, 'מי שאוכל לפני שהבטן מבקשת – ימצא את הרופא כחבר קרוב. — בנג''מין פרנקלין', 'אכילה מיותרת, סתם מתוך שעמום או הרגל – פוגעת בגוף. תאכל כשאתה באמת רעב ובזמנים קבועים.'),
(11, 'הליכה היא התרופה הטובה ביותר לאדם. — היפוקרטס', 'תנועה פשוטה כמו הליכה יכולה למנוע עשרות בעיות בריאות. היא חינמית, נגישה ומצילה חיים.'),
(12, 'תן לי שש שעות לכרות עץ – ואבזבז את הארבע הראשונות בהשחזת הגרזן. — אברהם לינקולן', 'הכנה מראש של לוז, ארוחות והליכות – חוסך המון טעויות, פיתויים והסחות דעת.'),
(13, 'יש לך בדיוק אותו מספר שעות ביום כמו לביונסה.', 'אל תשתמשו בתירוץ של "אין לי זמן". זה עניין של סדר עדיפויות – לא של זמן אמיתי.'),
(14, 'אין ראוי לאדם לשתות מים הרבה בתוך האכילה. — הלכות דעות ד'', 'שתייה מרובה בזמן האוכל מפריעה לעיכול. תשתו בין 5 ל-10 דקות לפניה וגם תרגישו שבעים יותר על הדרך.'),
(15, 'לא יאכל אדם אלא כשהוא רעב. — הלכות דעות ד'', 'אל תאכלו מתוך הרגל, שעמום או רגש. תאכלו רק כשאתם מרגישים רעב אמיתי – זו פעולה שמובילה לאורח חיים יותר בריא.'),
(16, 'בריאות היא לא דבר שניתן לקנות ברגע, היא תוצאה של השקעה יומיומית. — רוברט אורבן', 'הבריאות היא תוצאה של החלטות יומיומיות ואורח חיים נכון, ולא משהו שניתן לרכוש באופן מיידי.'),
(17, 'לא רק מה שאתה אוכל – אלא מתי ואיך אתה אוכל.', 'אכילה בלחץ, בזמן לא קבוע, או מול מסך – משפיעה לרעה על העיכול והבריאות. סדר חשוב לא פחות מהתוכן.'),
(18, 'השינוי מתחיל בפעולות קטנות, לא בהחלטות דרמטיות. — ג''יימס קליר', 'כל צעד קטן מקדם אותכם קדימה בלי לחץ.'),
(19, 'שינה עמוקה בתחילת הלילה היא המשובחת ביותר. — הלכות דעות ד'', 'שינה איכותית בלילה – בפרט בשעות הראשונות – היא חיונית לבריאות הגוף והנפש. סדר יום קבוע עוזר בזה מאוד.'),
(20, 'שמירה על הגוף בריא – היא חובה. אחרת לא נוכל לשמור על ראש צלול. — בודהה', 'הגוף והנפש קשורים. הליכה ואכילה מסודרת לא רק משפרים את הגוף – אלא גם את המוח, הריכוז והשלווה.'),
(21, 'משמעת קטנה שחוזרת כל יום – יוצרת הצלחות גדולות. — ג''ון מקסוול', 'הליכה, זמני אוכל קבועים, מים לפני ארוחה – הדברים הקטנים האלה מצטברים ויוצרים שינוי מדהים.'),
(22, 'הצלחה היא תוצאה של חזרתיות יומיומית. — דווין ג''ונסון', 'הצלחה לא נבנית ביום. היא נבנית מהרגלים קטנים שחוזרים על עצמם שוב ושוב. כל פעם שאתם בוחרים להיצמד לתוכנית – אתם בונים את ההצלחה שלכם.'),
(23, 'היה מזונך תרופתך ותרופתך מזונך. — היפוקרטס', 'האוכל שלכם הוא כוח ריפוי. השקעה בתזונה טובה היא השקעה בבריאות.'),
(24, 'רגע על השפתיים – לכל החיים על הירכיים.', 'תזכורת קלילה לבחור נכון, גם כשקשה ובא לברוח למתוק.'),
(25, 'רופא העתיד לא יטפל עם תרופות, אלא יירפא וימנע מחלות בעזרת תזונה. — תומאס אדיסון', 'אדיסון אמר שהרפואה של העתיד תתמקד בתזונה נכונה כדרך למנוע ולטפל במחלות, במקום תרופות.'),
(26, 'השינוי הטוב ביותר הוא זה שאתה לא צריך להתאמץ לשמור עליו. — גרג נוקולס', 'המאמץ האמיתי הוא בבנייה – לא בתחזוקה.'),
(27, 'שיהיה מזונך תרופתך – ותרופתך מזונך. — היפוקרטס', 'הגוף שלכם נבנה מהמזון שאתם אוכלים. ככל שתאכלו טוב יותר – כך תזדקקו פחות לרופאים ותחיו יותר.'),
(28, 'לאכול זו צורך, אך לאכול בתבונה זו אומנות. — לה רושפוקו', 'לאכול זה קל. לאכול נכון וחכם – זו אומנות של בחירה מודעת ויש לבנות אותה.'),
(29, 'הדרך היחידה לעשות עבודה נהדרת היא לאהוב את מה שאתה עושה. — סטיב ג''ובס', 'גם בתהליך ירידה במשקל, כשאתם נהנים מהדרך, קל יותר להתמיד ולהשקיע מאמץ.'),
(30, 'תדאג לגוף שלך, הוא ידאג לך בחזרה.', 'כשאתם מטפלים בגוף שלכם, הוא מחזיר לכם בשפע – באנרגיה, בכוח וברוגע.'),
(31, 'משמעת היא הבחירה בין מה שאתה רוצה עכשיו לבין מה שאתה רוצה יותר מכל. — אברהם לינקולן', 'תזכרו מה המטרה הגדולה שלכם, גם כשיש משהו קטן שמפתה אותכם - תישארו ממוקדים.'),
(32, 'האוכל שאתה אוכל יכול להיות התרופה החזקה ביותר שלך או הרעל האיטי ביותר שלך. — אן ויגמור', 'מה שאתם בוחרים לשים בצלחת משפיע ישירות על הבריאות שלכם, לטוב או לרע.'),
(33, 'הזמן יקר יותר מכסף. אפשר להרוויח עוד כסף - אבל אי אפשר להרוויח עוד זמן.', 'אל תבזבזו את הזמן שלכם על שטויות - הוא המשאב הכי יקר שיש. תכננו אותו כמו שהייתם מתכננים תקציב.'),
(34, 'הבריאות אינה מוערכת עד שמגיעה המחלה. — תומאס פולר', 'אל תחכו לבעיות כדי להעריך את הבריאות שלכם – תשמרו עליה מראש כל יום.'),
(35, 'בריאות היא מערכת יחסים בינך לבין הגוף שלך. — טרי גילמנט', 'אורח חיים בריא זה לא ללכת לפי תפריט – אלא מערכת יחסים של הקשבה וכבוד לגוף שלך.'),
(36, 'מי שחושב שאין לו זמן לאכול בריא – ימצא בהמשך זמן למחלה. — אדוארד סטנלי', 'לחיות בריא יחסוך לכם הרבה בעיות בעתיד והרבה כסף.'),
(37, 'שום מאכל טעים אינו שווה לתחושה של גוף בריא.', 'ההרגשה הטובה של גוף בריא שווה יותר מכל פיתוי רגעי.'),
(38, 'חיצוניות בריאה מתחילה מבפנים. — רוברט אורבן', 'תזונה נכונה נראית גם כלפי חוץ – בעור, באנרגיה ובחיוך.'),
(39, 'אוכל טוב מסתיים בשיחה טובה. — ג''וליה צ''יילד', 'האוכל הוא לא רק דלק – אלא גם חוויה, שיחה, ושמחה. תאכלו בריא ותהנו מזה.'),
(40, 'אתה מה שאתה אוכל. — אנטל ברילאט-סברין', 'מה שאתם מכניסים לגוף שלכם בונה גם את הבריאות וגם את ההרגשה שלכם.'),
(41, 'הבריאות היא העושר האמיתי ולא זהב וכסף. — מהטמה גנדי', 'הבריאות שלכם יקרה מפז, והיא הבסיס לכל דבר טוב אחר בחיים שלכם.'),
(42, 'הכוח שלנו טמון ביכולת שלנו לשנות את עצמנו. — סטיבן קובי', 'הבריאות שלכם בידיים שלכם. כל שינוי קטן שאתם בוחרים היום יוצר מחר חזק ובריא יותר.'),
(43, 'אני שונא כל דקה של אימון, אבל אמרתי לעצמי: אל תפרוש. סבול עכשיו ותחייה את שארית חייך כאלוף. — מוחמד עלי', 'כל מאמץ שאתם משקיעים היום יבנה את הגוף והאורח חיים שאתם חולמים עליהם. תשקיעו בעצמכם עכשיו - ותהיו אלופים אחר כך.'),
(44, 'אם אתה לא יכול לעוף, רוץ. אם אתה לא יכול לרוץ, לך. אם אתה לא יכול ללכת, זחול. כל עוד אתה לא עוצר. — מרטין לותר קינג', 'כל צעד קטן שנעשה בדרך הוא צעד לעבר המטרה. כל עוד לא עוצרים, אפשר להתקדם בכל מצב.'),
(45, 'כשאתה בונה את הגוף שלך, אתה בונה גם את הנפש שלך. — ארנולד שוורצנגר', 'תהליך של אימון גופני הוא גם תהליך של בניית אופי וביטחון עצמי. הגוף והראש מתפתחים יחד.'),
(46, 'כשזה נהיה קשה, זה הרגע שבו רוב האנשים מפסיקים – ואתה רק מתחיל. — דייוויד גוגינס', 'הקושי הוא רק השער – תעברו דרכו ותגלו גרסה חדשה שלכם.'),
(47, 'השינוי לא יקרה אם תחכה. אתה זה שחיכית לו. — ברק אובמה', 'אף אחד לא יבוא להציל אותכם. אתם אלו שמשנים את החיים שלכם – עם כל חזרה, כל אימון וכל החלטה.'),
(48, 'גבולות, כמו פחדים, הם לעיתים רק אשליה. — מייקל ג''ורדן', 'אין באמת גבולות למה שאתם יכולים להשיג. אם תאתגרו את עצמכם, אתם תפתיעו את עצמכם בתוצאה.'),
(49, 'בריאות לא נקנית – היא נבנית. — ג''ים רון', 'כל בחירה בריאה, כל אימון, כל יום – זו לבנה בבניין שנקרא אתה.'),
(50, 'המכשולים הם הדברים שאתה רואה כשאתה מסיר את העיניים מהמטרה. — הנרי פורד', 'תתמקדו במטרה שלכם, לא בקשיים בדרך. תמיד יהיו עליות וירידות, תהיו ממוקדים.'),
(51, 'הצלחה היא לא פעולה חד-פעמית, היא הרגל. — אריסטו', 'התמדה היא הכוח. ועל מנת להמשיך לשמור עליה, עלינו להוסיף אותה בתור הרגל.'),
(52, 'אין שום דרך לעקוף את העבודה הקשה, לא משנה מה יגידו לך. — אלן דג''נרס', 'הדרך היחידה להתקדם – היא דרך עבודה. ואת זה אף אחד לא יכול לעשות במקומך.'),
(53, 'כשאתה מרגיש שאתה רוצה לוותר – תזכור למה התחלת. — ג''ף באזוס', 'תמיד תחזור/רי לרגע שבו החלטת להשתנות. שם נמצא הכוח שלך.'),
(54, 'ההצלחה מגיעה לאנשים שלא מתייאשים. — וורן באפט', 'התוצאה היא של מי שעקבי – לא של מי שהיה הכי מהיר.'),
(55, 'לא תמצא זמן לאימון – תצטרך ליצור אותו. — ג''ק לאלאן', 'הרגע הכי טוב אף פעם לא יגיע. תשים זמן בשביל עצמך בלוז – ואל תתנצל על זה.'),
(56, 'אל תיתן לאתמול לקחת יותר מדי מהיום. — וויל רוג''רס', 'כל יום הוא הזדמנות חדשה. אל תיתנו לעבר לעכב אותכם – במיוחד עכשיו כשאתם נבנים מחדש.'),
(57, 'מה שאתה חושב, אתה הופך להיות. — בודהה', 'המחשבות שלך יוצרות את המציאות שלך. תאמין שאתה יכול – ותתחיל לפעול כמו מישהו שכבר שם.'),
(58, 'הדבר הכי קשה הוא להחליט לפעול. השאר זה רק התמדה. — אמיליה ארהארט', 'אם כבר התחלת – אתה מעבר לחלק הקשה. עכשיו פשוט תמשיך.'),
(59, 'מי שרוצה משהו שמעולם לא היה לו – צריך להיות מוכן לעשות משהו שמעולם לא עשה. — תומאס ג''פרסון', 'אם תמשיך לעשות את מה שתמיד עשית – תישאר בדיוק איפה שאתה.'),
(60, 'מה שעובד לאורך זמן הוא מה שמתאים לחיים שלך, לא למה שנראה טוב על הנייר.', 'תהליך מנצח משתלב במשפחה, בעבודה ובשגרה – לא נלחם בהם.'),
(61, 'הכוח לא בא ממה שאתה מצליח לעשות. הוא בא מהתגברות על מה שחשבת שלא אפשרי.', 'כל פעם שאתה עושה משהו שחשבת שלא תוכל – אתה מגדיל את עצמך.'),
(62, 'אין תחליף לעבודה קשה. — תומאס אדיסון', 'אי אפשר לעקוף את זה. הדרך היחידה – היא לעבור דרכה.'),
(63, 'האימון לא הופך אותך מושלם – הוא הופך אותך עקבי. — טום ביליו', 'ההתמדה מנצחת כל כישרון. אל תחפש תוצאה מיידית – תיצור בסיס חזק שישאר איתך לתמיד.'),
(64, 'אתה לא צריך לראות את כל המדרגות – פשוט תעלה את הראשונה. — מרטין לותר קינג', 'אתה לא צריך לדעת איך כל התהליך ייראה. רק תתחיל – השאר יקרה תוך כדי.'),
(65, 'בריאות היא לא יעד – היא דרך חיים. — ג''יליאן מייקלס', 'אתה לא "בתהליך" – אתה משנה גישה. זה לא משהו זמני.'),
(66, 'כל מה ששווה משהו – לא בא בקלות. — תדי רוזוולט', 'הגוף שאתה בונה – שווה את כל רגעי המאמץ והקושי.'),
(67, 'הגוף משקף את הבחירות שלך. — מייקל פולן', 'אתה רואה במראה את מה שאתה בוחר כל יום מחדש. תבחר נכון.'),
(68, 'הכאב זמני. הוויתור נמשך לנצח. — לאנס ארמסטרונג', 'אימון קשה ייגמר. חרטה על זה שלא התאמצת וויתרת לעצמך – תישאר איתך.'),
(69, 'זה לא קשור לשלמות. זה קשור למאמץ. — ג''יליאן מייקלס', 'אל תחפש להיות מושלם – תתמיד. זה מה שמביא תוצאות.'),
(70, 'האדם שמזיז הרים התחיל בלסחוב אבנים קטנות. — קונפוציוס', 'גם שינוי גדול מתחיל בצעד קטן. כל אימון נחשב.'),
(71, 'תזונה טובה היא לא עונש – היא חופש. — ג''ושוע רוזנטל', 'לאכול בריא זה לא להגביל – זה להשתחרר מהתמכרויות, עייפות, כאבים.'),
(72, 'אם משהו עומד בינך לבין ההצלחה שלך – תזיז אותו. אל תיתן לו לעצור אותך. — דוויין ג''ונסון', 'אין תירוצים. יש החלטה – ויש פעולה.'),
(73, 'כל מערכת טובה מפשטת את הדרך.', 'פחות דרמות – יותר עקביות.'),
(74, 'ההצלחה היא הליכה מכישלון לכישלון מבלי לאבד את ההתלהבות. — וינסטון צ''רצ''יל', 'גם אם זה קשה, כל עוד אתה ממשיך לנסות – אתה בדרך לנצח.'),
(75, 'המוטיבציה היא מה שגורמת לך להתחיל. ההרגלים הם מה שמשאיר אותך בתנועה. — ג''ים ריון', 'ההתחלה זה ניצוץ. אבל ההרגלים – זה מה שבונה לך את אורח החיים באמת.'),
(76, 'שנאתי כל רגע של האימונים. אבל אמרתי לעצמי – אל תוותר. תסבול עכשיו ותחיה את שאר חייך כאלוף. — מוחמד עלי', 'המחיר שאתה משלם עכשיו – הוא החופש שתרוויח כל החיים.'),
(77, 'המגבלה היחידה למימוש של מחר – היא הספקות של היום. — פרנקלין ד. רוזוולט', 'הגוף שאתה רוצה מתחיל בהחלטה להאמין שאתה מסוגל ולעשות פעולות.'),
(78, 'הרבה מהכישלונות באים מאנשים שלא הבינו כמה קרובים הם היו להצלחה כשוויתרו. — תומאס אדיסון', 'אל תעצור באמצע – הגוף שאתה רוצה אולי כבר מעבר לפינה.'),
(79, 'התמדה היא לא מירוץ מהיר, היא מרתון שנמשך יום אחרי יום. — אנג''לה דאקוורת''', 'תהליך ירידה במשקל ובניית גוף הוא ריצת מרתון – לא ספרינט.'),
(80, 'אל תספר לי כמה קשה עבדת. תגיד לי מה השגת.', 'לא מספיק להזיע – חשוב להתמקד בתוצאה ובשיפור אמיתי.'),
(81, 'אנחנו לא מפסיקים לשחק כי אנחנו מזדקנים; אנחנו מזדקנים כי אנחנו מפסיקים לשחק. — ג''ורג'' ברנרד שו', 'תנועה, משחק ופעילות – הם סוד הנעורים האמיתי.'),
(82, 'מי שלא מתקדם – הולך אחורה. — יוהאן פון גתה', 'שמירה על סטטוס-קוו היא אשליה – או שאתה בונה את הגוף שלך, או שאתה מרפה ממנו.'),
(83, 'האדם עם כוח הרצון הוא בלתי ניתן לעצירה. — וינס לומברדי', 'לא הכישרון מנצח – אלא הרצון שלא לוותר.'),
(84, 'אינך יכול לחצות את הים רק מלעמוד ולהביט על המים. — רבינדרנת טאגור', 'אי אפשר לחצות ים בלי לעלות לסירה ולהתחיל לחתור – אי אפשר לשמור על תוצאה בלי להמשיך לפעול. זה לא סיום התהליך, זה התחלה של אורח חיים חדש.'),
(85, 'יש סיבה שאני מנצח אותם - הם מתחרים בי ואני מתחרה בגרסה הטובה ביותר שאני יכול להיות. — מייקל ג''ורדן', 'אל תתחרה באחרים – תתחרה בגרסה הטובה ביותר של עצמך.'),
(86, 'כל יום הוא הזדמנות להתחיל מחדש. — בובי אוניל', 'לא משנה מה קרה אתמול, היום הוא שלך.'),
(87, 'הרגלים קטנים מפחיתים עומס מנטלי גדול. — גרג מקיואן', 'פשטות יוצרת שקט – ושקט יוצר התמדה.'),
(88, 'משמעת היא הגשר בין מטרות להישגים. — ג''ים רון', 'מוטיבציה באה והולכת, אבל משמעת בונה תוצאה שנשארת.'),
(89, 'זה לא מי שאתה – זה מה שאתה עושה שוב ושוב. — ג''יימס קליר', 'זהות נבנית מההרגלים, לא מהכוונות.'),
(90, 'אל תחפש קיצוניות, חפש עקביות. — טים גרובר', 'עקביות מנצחת הכול.'),
(91, 'אתה תמיד מרחק החלטה אחת מחיים אחרים. — מל רובינס', 'שינוי בגוף מתחיל בהחלטה אחת אמיצה.'),
(92, 'האדם שאתה הופך להיות חשוב יותר מהמטרה שאתה משיג. — ג''ים רון', 'הגוף הוא תוצר לוואי של האדם שאתה בונה.'),
(93, 'אתה לא צריך יותר כוח רצון – אתה צריך מערכת. — סקוט אדמס', 'סביבה והרגלים מנצחים רצון וחשקים.'),
(94, 'התקדמות לא נראית ליניארית – אבל היא מצטברת.', 'יהיו ימים שאתה מרגיש תקוע, אבל הגוף ממשיך להסתגל גם כשלא רואים שינוי מיד.'),
(95, 'הדרך הטובה ביותר לחזות את העתיד היא ליצור אותו. — פיטר דרוקר', 'העתיד הגופני שלך נבנה עכשיו.'),
(96, 'הצלחה אינה סופית, כישלון אינו קטלני – האומץ להמשיך הוא שקובע. — וינסטון צ''רצ''יל', 'מי שממשיך גם אחרי נפילות הוא זה שבאמת משתנה.'),
(97, 'מה שאתה עושה היום יכול לשפר את כל המחרים שלך. — ראלף מרסטון', 'כל יום טוב בתוך התהליך עושה אפקט של ריבית דריבית שמצטבר.'),
(98, 'מי שיש לו למה חזק מספיק – ימצא כמעט כל איך. — פרידריך ניטשה', 'כשאתה מחובר לסיבה, גם ימים קשים לא שוברים אותך.'),
(99, 'אל תמדוד הצלחה לפי מה שהשגת, אלא לפי המכשולים שהתגברת עליהם. — בוקר טי וושינגטון', 'עצם זה שאתה עדיין ממשיך אומר שכבר התקדמת.'),
(100, 'הכאב הוא זמני. הוויתור נשאר לנצח. — לאנס ארמסטרונג', 'הקושי של עכשיו יעבור, אבל הזהות שאתה בונה תישאר.'),
(101, 'מי ששולט בהרגלים שלו – שולט בעתיד שלו. — סטיבן קובי', 'התוצאה תגיע מעצמה כשההרגלים במקום.'),
(102, 'אל תחכה לרגע המושלם. הוא לא יגיע. — נפוליאון היל', 'תהליך עובד גם כשלא הכול מושלם.'),
(103, 'מה שאתה עושה בעקביות חשוב יותר ממה שאתה עושה באינטנסיביות. — ג''ון וודן', 'קיצוניות נשרפת מהר, עקביות מחזיקה שנים.'),
(104, 'לא כל יום טוב, אבל יש משהו טוב בכל יום. — אליס מורס ארל', 'גם יום בינוני שומר אותך במסלול.'),
(105, 'הצלחה נבנית בשגרה, לא ברגעים גדולים. — ג''ון וודן', 'היום-יום הוא זה שמפסל את הגוף.'),
(106, 'אם אתה עדיין בתהליך – אתה כבר רחוק מאיפה שהתחלת. — ג''ים רון', 'תזכור מאיפה באת לפני שאתה שופט איפה אתה.'),
(107, 'מה שאתה עושה בכל יום חשוב יותר ממה שאתה עושה פעם בכמה זמן. — ג''יימס קליר', 'שינוי אמיתי לא נבנה מקיצוניות אלא מהפעולות הקטנות שאתה חי איתן בשלום.'),
(108, 'אם אינך יכול לשמור על זה לנצח – אל תתחיל עם זה בכלל.', 'תהליך טוב הוא כזה שאתה יכול לחיות איתו, לא לשרוד אותו.'),
(109, 'הרגלים צריכים לשרת אותך, לא להעניש אותך. — ג''יימס קליר', 'אם הדרך מרגישה כמו מלחמה, היא לא תחזיק. הרגל נכון משתלב בחיים.'),
(110, 'התמדה נוצרת מפשטות, לא מקשיחות. — גרג מקיואן', 'ככל שהדרך פשוטה יותר – כך קל יותר להתמיד בה לאורך זמן.'),
(111, 'אתה לא צריך יותר כוח רצון, אתה צריך פחות חיכוך. — ג''יימס קליר', 'כשסביבה והרגלים עובדים בשבילך, אין צורך להילחם בעצמך.'),
(112, 'מה שעובד הוא לא מה שהכי קשה – אלא מה שאתה באמת עושה. — דן ג''ון', 'תוצאה מגיעה מיישום יומיומי, לא משיטות קיצון.'),
(113, 'אם תהליך דורש סבל – הוא לא חכם.', 'תזונה בריאה אמורה לשפר לך את החיים, לא להפוך אותם לעונש.'),
(114, 'הדרך הקלה יותר היא לעיתים הדרך הנכונה יותר. — טים פריס', 'מה שקל לחזור עליו – מנצח בטווח הארוך.'),
(115, 'הרגלים טובים אמורים להפחית מאמץ, לא להוסיף אותו. — צ''רלס דוהיג', 'כשהרגל יושב נכון, אתה לא צריך להפעיל כוח כל פעם מחדש.'),
(116, 'עקביות חשובה יותר משלמות. — ברנה בראון', 'לא צריך להיות מושלם כדי להצליח, צריך להיות שם.'),
(117, 'הצלחה אמיתית היא כזו שלא דורשת ממך לוותר על החיים שלך. — טוני רובינס', 'גוף חזק צריך להתאים לחיים עם משפחה, עבודה והנאות.'),
(118, 'אתה לא צריך להגיד לא – אתה צריך לדעת מתי ואיך להגיד כן.', 'איזון חכם מנצח איסורים מוחלטים.'),
(119, 'מה שמחזיק לאורך זמן הוא מה שמרגיש טבעי. — ג''יימס קליר', 'כשזה חלק מהשגרה, אין מאבק.'),
(120, 'המטרה של הרגלים היא לפשט את החיים, לא להכביד עליהם. — סטיבן קובי', 'הרגל נכון חוסך החלטות ומפנה אנרגיה.'),
(121, 'אם אתה חייב מוטיבציה כל יום – המערכת שבורה. — סקוט אדמס', 'מערכת טובה עובדת גם בלי חשק.'),
(122, 'התנהגות חכמה מנצחת משמעת קשוחה. — ריי דליו', 'חוקים פשוטים וברורים עובדים טוב יותר ממלחמות פנימיות.'),
(123, 'הצלחה היא לא כמה התאמצת – אלא כמה זמן החזקת. — סיימון סינק', 'קיימות חשובה יותר מאינטנסיביות.'),
(124, 'מה שלא משתלב באורח החיים – נעלם.', 'רק הרגלים שמתאימים לחיים האמיתיים שורדים.'),
(125, 'אתה לא בונה רק גוף, אתה בונה שגרה – והגוף מגיע איתה. — דן ג''ון', 'תוצאה היא תוצר לוואי של התנהלות יומית נכונה.'),
(126, 'המפתח הוא לא לוותר על הנאה, אלא לנהל אותה.', 'כשאין איסור מוחלט – אין גם פיצוץ.'),
(127, 'הרגלים טובים צריכים להרגיש אפשריים גם ביום גרוע. — ג''יימס קליר', 'אם זה עובד רק ביום מושלם – זה לא עובד.'),
(128, 'אם הדרך קשה מדי – אנשים לא אשמים, השיטה אשמה.', 'שיטה חכמה לוקחת בחשבון בני אדם אמיתיים.'),
(129, 'אכול כדי לחיות, אל תחיה כדי לאכול. — סוקרטס', 'תן לאוכל מקום חשוב – אבל שלא ינהל את החיים שלך.'),
(130, 'המטרה היא חיים טובים יותר, לא רק גוף רזה יותר.', 'כשהחיים משתפרים – הגוף כבר מצטרף.'),
(131, 'הרגלים טובים אמורים להקל עליך, לא להקשות עליך. — ג''יימס קליר', 'כשמשהו בנוי נכון, אתה לא צריך להפעיל כוח רצון בכל פעם מחדש.'),
(132, 'הבריאות היא הנכס הגדול ביותר שלנו. — תומאס ג''פרסון', 'שום דבר לא משתווה להרגשה של גוף מתפקד, חזק, בריא. כל תרגיל – הוא השקעה.'),
(133, 'המטרה של משמעת היא חופש, לא סבל. — ג''וקו ווילינק', 'כשיש הרגלים ברורים, אתה לא עסוק בהחלטות ומאבקים פנימיים.'),
(134, 'הרגלים הם הדרך הכי פשוטה להפסיק לנהל משא ומתן עם עצמך. — צ''רלס דוהיג', 'פחות החלטות = יותר יציבות לאורך זמן.'),
(135, 'מה שקל לעשות – קל גם להתמיד בו. — טים פריס', 'פשטות היא יתרון, לא חולשה.'),
(136, 'עקביות מנצחת אינטנסיביות בכל משחק ארוך. — סיימון סינק', 'שינוי גוף הוא משחק ארוך, לא אתגר של 30 יום.'),
(137, 'אל תבנה תהליך שאתה צריך הפסקה ממנו.', 'אם צריך לברוח מהשיטה – היא לא מחזיקה.'),
(138, 'המטרה היא לא להיות מושלם, אלא להיות יציב. — ברנה בראון', 'יציבות מאפשרת טעויות בלי לפרק את הכול.'),
(139, 'שום דבר שאפשר לטפל בו בעזרת תזונה – אל יטופל בדרך אחרת. — הרמב"ם', 'הרבה בעיות בריאות אפשר לפתור קודם כל דרך התזונה. אל תזלזל בכוח של האוכל.'),
(140, 'הרגלים נועדו לפנות אנרגיה לדברים שחשובים באמת. — סטיבן קובי', 'פחות מאמץ יומיומי = יותר מקום לחיים עצמם.'),
(141, 'תהליך טוב לא דורש ממך להיות אדם אחר. — טוני רובינס', 'הוא עובד עם מי שאתה, לא מי שאתה אמור להיות.'),
(142, 'אם זה עובד רק כשיש מוטיבציה – זה לא באמת עובד. — סקוט אדמס', 'מערכת טובה מחזיקה גם בימים אפורים.'),
(143, 'העתיד תלוי במה שאתה עושה היום. — מהטמה גנדי', 'כל פעולה קטנה היום קובעת איך הגוף שלך ייראה מחר.'),
(144, 'הצלחה היא לא ויתור על הנאות, אלא ניהול שלהן. — ריי דליו', 'שליטה חכמה עדיפה על איסורים מוחלטים.'),
(145, 'מה שמתאים לאורח החיים שלך – מחזיק.', 'רק שיטות שמתחשבות בחיים האמיתיים שורדות.'),
(146, 'המטרה היא לא משמעת קשוחה, אלא הרגלים חכמים. — ג''יימס קליר', 'חוכמה מפחיתה מאבק.'),
(147, 'כשאין דרמה – יש תוצאות. — דן ג''ון', 'שקט, פשוט, עקבי – זה מנצח.'),
(148, 'הרגלים טובים אמורים לעבוד גם כשאתה עייף. — ג''יימס קליר', 'אם זה דורש אנרגיה שאין לך – זה לא בר-קיימא.'),
(149, 'הגוף משתנה כשאורח החיים משתנה.', 'זה לא דיאטה זמנית, אלא דרך חיים אחרת.'),
(150, 'השיטה הנכונה היא זו שלא דורשת ממך להילחם בעצמך.', 'כשאין מלחמה – יש התמדה.'),
(151, 'המטרה היא חיים בריאים יותר, לא רק משקל נמוך יותר.', 'המשקל לא צריך לקחת את מלוא הפוקוס, החוויות והבריאות שלנו כן.'),
(152, 'הרגלים טובים מפשטים החלטות. — ג''יימס קליר', 'כשיש הרגלים ברורים, אתה לא צריך לחשוב כל יום מחדש מה נכון.'),
(153, 'מה שאתה יכול לעשות גם ביום עמוס – זה מה שיחזיק. — דן ג''ון', 'תהליך חזק נמדד ביום קשה, לא ביום מושלם.'),
(154, 'שלמות היא אויב ההתמדה. — ברנה בראון', 'כשמשחררים מושלמות וכן נותנים מקום להנאות, קל יותר להישאר בתהליך.'),
(155, 'תהליך טוב לא דורש ממך לוותר על עצמך. — סיימון סינק', 'הוא אמור לחזק אותך, לא לוותר על חוויות בחיים.'),
(156, 'מה שלא משתלב בשגרה – נעלם.', 'רק הרגלים שמתאימים לחיים האמיתיים שורדים לאורך זמן.'),
(157, 'הרגלים עובדים טוב יותר מחוקים נוקשים. — צ''רלס דוהיג', 'חוקים שוברים, הרגלים מחזיקים.'),
(158, 'המפתח הוא לא לאכול פחות, אלא להתנהל חכם יותר.', 'ניהול נכון עדיף על איסור.'),
(159, 'הצלחה אמיתית לא דורשת ממך לספור כל דבר.', 'שליטה חכמה לא חייבת להיות אובססיבית.'),
(160, 'הרגלים טובים נותנים שקט מנטלי. — גרג מקיואן', 'פחות החלטות יומיומיות = פחות עייפות.'),
(161, 'תהליך שלא מאפשר הנאה – לא יחזיק.', 'הנאה מבוקרת עדיפה על איסור מוחלט.'),
(162, 'התמדה לא דורשת קורבן, אלא תכנון נכון. — דן ג''ון', 'בניית הרגל חכם מחליפה סבל בעקביות טבעית.'),
(163, 'הצלחה היא לא כמה אתה מוותר, אלא כמה אתה נהנה בדרך.', 'הנאה מחושבת היא חלק מהתהליך שמחזיק.'),
(164, 'הבריאות שלך והחשבון בנק שלך דומים – ככל שתכניס יותר, תוכל להוציא יותר. — ג''יין פונדה', 'כל אימון שאתה עושה היום – הוא ריבית לגוף שלך מחר.'),
(165, 'אל תנסה לשבור את עצמך – תשתמש בכוחותיך. — מארק מנסון', 'כשאתה עובד עם עצמך, לא נגד עצמך, קל להתמיד לאורך זמן.'),
(166, 'אל תנסה להילחם בכוחות שלך – תבנה מערכת שתעבוד עם הכוחות האלה. — מארק מנסון', 'ניהול נכון של אנרגיה והרגלים מנצח את כוח הרצון.'),
(167, 'ישיבה היא העישון החדש. — ד"ר ג''יימס לוין', 'הרבה ישיבה מזיקה כמו עישון. גם אם אתה מתאמן – תדאג לזוז במהלך היום, אפילו בהליכות קצרות.'),
(168, 'המסע הזה לא היה רק על שינוי הגוף – אלא על יצירת הרגלים שמחזיקים אותך לאורך כל החיים. — ג''יימס קליר', 'בכל יום של התהליך למדת שהשינוי האמיתי לא נמדד במאמץ רגעי, אלא ביכולת לשלב הרגלים חכמים בחיי היום-יום. כל פעולה קטנה, כל החלטה חכמה, כל צעד עקבי – בנית את עצמך מחדש. עכשיו זה הרגע שלך להמשיך הלאה עם הכלים, החכמה והביטחון שצברת.')
